('478', '1', 'Modern 1 RK Studio Room for Working Bachelor in Rohini, New Delhi', 'Cozy, modern 1 RK studio apartment equipped with a private kitchenette, attached western bathroom, wardrobe, single bed, ceiling fan, and separate electric meter. Walkable distance to main road, gym, coaching institutes, and markets. Exact Address: Rohini, New Delhi. Landmark: Near Hauz Khas Village Link.', '1 RK', 'Fully Furnished', 'Rohini', 'New Delhi', '5000.00', '7500.00', '1', '1', '280', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?w=800&auto=format&fit=crop&q=80', '[\"https:\\/\\/images.unsplash.com\\/photo-1493809842364-78817add7ffb?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1505691938895-1758d7feb511?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1513694203232-719a280e022f?w=800&auto=format&fit=crop&q=80\"]', 'WiFi, AC / Cooler Point, Attached Bathroom, Kitchenette, 24x7 Water, Bike Parking', 'Bachelors & Working', '0', NULL, '84', 'available', '2026-07-31 17:43:49', '28.61590000', '77.20300000', 'Near Hauz Khas Village Link', '3 Months Min'),
('479', '1', 'Commercial Shop / Office Space on Main Road in Hauz Khas, New Delhi', 'Prime ground-floor commercial showroom / office space with 15 feet front road frontage, rolling shutter, vitrified tile flooring, and immense footfall. Best suited for clinic, pharmacy, boutique, coaching center, CA/law office, or retail brand. Exact Address: Hauz Khas, New Delhi. Landmark: Near Connaught Place Outer Circle.', 'Commercial Shop', 'Unfurnished', 'Hauz Khas', 'New Delhi', '8800.00', '26400.00', '0', '1', '350', 'https://images.unsplash.com/photo-1505691938895-1758d7feb511?w=800&auto=format&fit=crop&q=80', '[\"https:\\/\\/images.unsplash.com\\/photo-1505691938895-1758d7feb511?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1513694203232-719a280e022f?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1502005229762-ee1b2b8ab98f?w=800&auto=format&fit=crop&q=80\"]', 'Main Road Facing, High Footfall, Glass Front, Shutter, 24x7 Water, Electricity Backup', 'Commercial / Business', '0', NULL, '59', 'available', '2026-08-12 10:43:49', '28.61190000', '77.21000000', 'Near Connaught Place Outer Circle', '11 Months Agreement'),
('480', '1', '2-Bed Sharing Room with Study Table & Cooler in Connaught Place, New Delhi', 'Economical and friendly 2-sharing room designed for competitive exam students (UPSC, BPSC, SSC, NEET, JEE). Includes 2 wooden beds with mattresses, dual study tables with charging sockets, separate clothes wardrobes, and unlimited WiFi. Exact Address: Connaught Place, New Delhi. Landmark: Near Rohini West Metro.', 'Single Room', 'Fully Furnished', 'Connaught Place', 'New Delhi', '1600.00', '1600.00', '1', '1', '200', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=800&auto=format&fit=crop&q=80', '[\"https:\\/\\/images.unsplash.com\\/photo-1513694203232-719a280e022f?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1502005229762-ee1b2b8ab98f?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1554995207-c18c203602cb?w=800&auto=format&fit=crop&q=80\"]', 'High-Speed WiFi, RO Water, Study Table, Individual Locker, 24x7 Water, Bike Parking', 'Students Only', '0', NULL, '51', 'rented', '2026-08-11 10:43:49', '28.62490000', '77.19800000', 'Near Rohini West Metro', '6 Months Min'),
('481', '1', 'Furnished 2 BHK Flat with Modular Setup & Inverter in Janakpuri, New Delhi', 'Move-in ready fully furnished 2 BHK home with double beds, sofa set in hall, 4-seater dining table, fitted AC, water purifier, geyser in both bathrooms, wide front balcony, and designated car parking slot. Exact Address: Janakpuri, New Delhi. Landmark: Near Janakpuri District Centre.', '2 BHK', 'Fully Furnished', 'Janakpuri', 'New Delhi', '11600.00', '23200.00', '2', '2', '920', 'https://images.unsplash.com/photo-1502005229762-ee1b2b8ab98f?w=800&auto=format&fit=crop&q=80', '[\"https:\\/\\/images.unsplash.com\\/photo-1502005229762-ee1b2b8ab98f?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1554995207-c18c203602cb?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1522708323590-d24dbb6b0267?w=800&auto=format&fit=crop&q=80\"]', 'AC, Modular Kitchen, Sofa Set, Dining Table, Geyser, Inverter Backup, Car Parking, CCTV', 'Family / Working Couples', '0', NULL, '82', 'available', '2026-08-07 19:43:49', '28.61690000', '77.21300000', 'Near Janakpuri District Centre', '11 Months Agreement'),
('482', '1', 'Independent Duplex Villa with Private Terrace & Lawn in Pitampura, New Delhi', 'Exclusive standalone duplex house featuring private open terrace, front garden area, covered car garage, 3 lavish bedrooms, 3 modern bathrooms, grand drawing room, and complete privacy in an upscale gated neighborhood. Exact Address: Pitampura, New Delhi. Landmark: Near Pitampura TV Tower.', '3 BHK', 'Fully Furnished', 'Pitampura', 'New Delhi', '26600.00', '53200.00', '3', '3', '1800', 'https://images.unsplash.com/photo-1554995207-c18c203602cb?w=800&auto=format&fit=crop&q=80', '[\"https:\\/\\/images.unsplash.com\\/photo-1554995207-c18c203602cb?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1522708323590-d24dbb6b0267?w=800&auto=format&fit=crop&q=80\",\"https:\\/\\/images.unsplash.com\\/photo-1502672260266-1c1ef2d93688?w=800&auto=format&fit=crop&q=80\"]', 'Private Terrace, Gated Compound, Car Garage, 2 ACs, 24x7 Water, Solar Backup, Garden Area', 'Family / Bank Officials', '0', NULL, '66', 'available', '2026-08-17 18:43:49', '28.62390000', '77.21600000', 'Near Pitampura TV Tower', '11 Months Agreement');
